def NativeLengthPhysical (p t q h l : ℝ) (L : Fin 4 → ℝ) : Prop :=
  (∀ i, 0 < L i) ∧ L 0 < 1 ∧ p * L 0 < 1 ∧ t * L 1 < 1 ∧
    q * L 1 < 1 ∧ q * L 2 < 1 ∧ h * L 2 < 1 ∧ l * L 3 < 1 ∧ L 3 < 1

blocks.body:
Let $0<p<1$, $0<l<1$, $1<q<h$, $s=\sigma(h,l)$ and
  $\Phi(p,q,h,l)\ge0$.  Then $0<s<1$, $hs<1$,
  $s^2(h^2-l^2)=1-l^2$, and
  \begin{enumerate}
    \item $s<p$;
    \item $\sqrt{1-p^2}\sqrt{1-s^2}\le(q-p)s$;
    \item $(1-p^2)(h^2-1)\le(1-l^2)(q-p)^2$;
    \item $1<pq$.
  \end{enumerate}

Let $0<p<1$, $p<t<q$, $1<q$, $1<h$, $0<l<1$ and $\mathrm{(HB)}$.  On
  the boundary of $[p,1]\times[l,1]$:
  \begin{enumerate}
    \item right face $u=1$, $l<v\le1$: $R_3<0$;
    \item top face $v=1$, $p<u\le1$: $R_1<0$;
    \item left face $u=p$, $l\le v<1$: $R_1>0$;
    \item bottom face $v=l$, $p\le u<1$: $R_3>0$;
    \item bottom-right corner: $R_1(1,l)=\Phi(p,t,q,l)$;
    \item top-left corner: with $\rho=\sqrt{1-p^2}/\sqrt{q^2-p^2}$,
      $R_3(p,1)=\arcsin(h\rho)+\arcsin l-\arcsin\rho-\pi/2$.
  \end{enumerate}
